let classSelected='';const attendanceDrafts=new Map();
let attendanceCache=null,attendanceCacheUser='';const attendanceMobileReady=import('./attendance-mobile.js');
function persistAttendanceDrafts(){return attendanceCache?.save(me,attendanceDrafts)}
window.addEventListener('beforeunload',event=>{if([...attendanceDrafts.values()].some(rows=>[...rows.values()].some(r=>r.dirty))){persistAttendanceDrafts();event.preventDefault();event.returnValue=''}});
function todayBR(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}`}
async function classList(){const unit=$('class-unit').value;if(!unit)return;const {classes}=await api('/classes?unit='+unit);$('class-list').replaceChildren();for(const c of classes){const b=el('button',`${c.day.split('-').reverse().join('/')} · ${c.time} · ${c.label}`,{class:'secondary registration-row'});b.addEventListener('click',action(()=>classDetail(c.id)));$('class-list').append(b)}if(!classes.length)$('class-list').append(el('p','Nenhuma chamada aberta neste núcleo. Escolha a turma e a data acima.'))}
async function loadAttendanceGroups(){if(!$('class-unit')?.value)return;const {groups}=await api('/groups?unit='+$('class-unit').value),select=$('class-group'),old=select.value;select.replaceChildren(el('option','Selecione a turma e horário',{value:''}));for(const g of groups.filter(g=>g.active))select.append(el('option',g.label+' · '+g.start_time+'–'+g.end_time+' · '+g.enrolled+' matriculados',{value:g.id}));if(groups.some(g=>g.id===old))select.value=old;const quick=$('today-classes');quick.replaceChildren();quick.hidden=me.role!=='teacher';if(me.role==='teacher'){quick.append(el('h3','Suas turmas de hoje · '+classUnits[$('class-unit').value]));const weekday=new Date(todayBR()+'T12:00:00Z').getUTCDay(),todays=groups.filter(g=>g.active&&g.weekdays.includes(weekday));for(const g of todays){const b=el('button','Abrir chamada · '+g.label+' · '+g.start_time+'–'+g.end_time,{type:'button',class:'today-class'});b.addEventListener('click',action(async()=>{select.value=g.id;$('class-form').elements.day.value=todayBR();const p=await api('/classes',{method:'POST',data:{group_id:g.id,day:todayBR()}});await classList();await classDetail(p.lesson.id)}));quick.append(b)}if(!todays.length)quick.append(el('p','Sem aula prevista para hoje neste núcleo. Use a turma e a data abaixo para conferir outra aula.'))}await classList()}
async function classDetail(id){classSelected=id;const {lesson,students:rows,can_write:canWrite}=await api('/classes/'+id+'/attendance');if(classSelected!==id)return;const box=$('class-detail');box.hidden=false;box.replaceChildren(el('h3',`${lesson.label} · ${lesson.day.split('-').reverse().join('/')} às ${lesson.time}`),el('p',classUnits[lesson.unit]+' · '+rows.length+' alunos na lista'),el('p','Toque para marcar cada aluno e depois salve. Não marcado não conta como falta. Os rascunhos ficam nesta aba durante sua sessão.'));
 const previous=canWrite?attendanceDrafts.get(id):undefined,draft=new Map(rows.map(r=>{const old=previous?.get(r.id);return [r.id,old?.dirty&&old.status!==r.status?old:{status:r.status,version:r.version,dirty:false}]}));attendanceDrafts.set(id,draft);const form=el('form'),summary=el('p','',{role:'status','aria-live':'polite'}),savebar=el('div',undefined,{class:'save-call'}),save=el('button','Salvar chamada'),mobile=await attendanceMobileReady;if(classSelected!==id)return;const tools=el('div');box.append(tools);mobile.mountAttendanceTools({el,field},tools,{rows,draft,form});form.classList.add('attendance-form');
 const update=()=>{const counts=Object.fromEntries(Object.keys(attendanceNames).map(k=>[k,rows.filter(r=>draft.get(r.id)?.status===k).length]));const changed=rows.filter(r=>draft.get(r.id)?.status!==r.status).length;summary.textContent=(rows.length-counts.unmarked)+' de '+rows.length+' marcados · '+counts.unmarked+' por preencher · '+changed+' alteração(ões) por salvar';save.textContent=changed?'Salvar '+changed+' alteração(ões)':'Sem alterações para salvar';save.disabled=!canWrite||!!lesson.cancelled||!changed;save.dataset.locked=String(save.disabled);persistAttendanceDrafts()};
 for(const r of rows){const line=el('fieldset',undefined,{class:'attendance-person',tabindex:'-1','data-student-id':r.id});line.append(el('legend',r.name),el('small',r.id));const buttons=el('div',undefined,{class:'attendance-options'});for(const [value,label]of [['present','Presente'],['absent','Faltou'],['justified','Justificada'],['unmarked','Limpar']]){const b=el('button',value==='unmarked'?'Limpar':label,{type:'button',class:'attendance-choice','aria-pressed':String(draft.get(r.id)?.status===value),'data-status':value});b.addEventListener('click',()=>{draft.set(r.id,{...draft.get(r.id),status:value,dirty:value!==r.status});for(const other of buttons.children)other.setAttribute('aria-pressed',String(other===b));update()});buttons.append(b)}if(canWrite&&!lesson.cancelled)line.append(buttons);else line.append(el('p',attendanceNames[r.status]));const attribution=el('details',undefined,{class:'attendance-attribution'});attribution.append(el('summary','Último lançamento'),el('p',r.updated_at?'Última alteração: '+(r.updated_by_name||'Conta registrada')+' · '+new Date(r.updated_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})+' (Brasília)':'Ainda sem lançamento.',{class:'muted'}));line.append(attribution);form.append(line)}
 update();if(!canWrite)box.append(el('p','Somente consulta. A chamada pode ser alterada pelo professor vinculado à turma, administradores e secretaria geral.',{class:'form-success'}));if(lesson.cancelled)box.append(el('p','Aula cancelada: '+lesson.cancellation_reason,{class:'form-error'}));savebar.setAttribute('aria-label','Resumo e salvamento da chamada');savebar.append(summary);if(canWrite)savebar.append(save);form.append(savebar);form.addEventListener('submit',action(async()=>{const changed=rows.filter(r=>draft.get(r.id)?.status!==r.status).map(r=>({id:r.id,status:draft.get(r.id).status,version:draft.get(r.id).version}));if(!changed.length){notice('Nenhuma marcação alterada.');return}const p=await api('/classes/'+id+'/attendance',{method:'POST',data:{rows:changed}});attendanceDrafts.delete(id);persistAttendanceDrafts();try{await classDetail(id)}catch{box.replaceChildren(el('p','Chamada salva. Não foi possível recarregar a tela. Abra a chamada novamente para conferir.',{role:'status',class:'form-success'}));const retry=el('button','Recarregar chamada salva',{type:'button',class:'secondary'});retry.addEventListener('click',action(()=>classDetail(id)));box.append(retry)}notice(p.message+' '+changed.length+' marcações gravadas.');document.dispatchEvent(new Event('portal:attendance-saved'))}));if(rows.length)box.append(form);else box.append(el('p','Esta turma ainda não tem alunos matriculados. A administração deve conferir as matrículas antes de abrir uma nova aula.'));const refresh=el('button','Descartar rascunho e recarregar chamada',{type:'button',class:'secondary'});refresh.addEventListener('click',action(async()=>{attendanceDrafts.delete(id);persistAttendanceDrafts();await classDetail(id)}));box.append(refresh);
 const cancellation=el('details');cancellation.append(el('summary',lesson.cancelled?'Reabrir aula cancelada':'A aula não ocorreu? Registrar cancelamento'));const cf=el('form');field(cf,'Motivo do cancelamento ou reabertura','reason','').required=true;cf.append(el('button',lesson.cancelled?'Reabrir aula':'Confirmar cancelamento'));cf.addEventListener('submit',action(async()=>{const p=await api('/classes/'+id+'/cancellation',{method:'POST',data:{cancelled:!lesson.cancelled,reason:cf.elements.reason.value}});attendanceDrafts.delete(id);persistAttendanceDrafts();await classDetail(id);notice(p.message);document.dispatchEvent(new Event('portal:attendance-saved'))}));cancellation.append(cf);if(canWrite)box.append(cancellation);const historyBox=el('section');box.append(historyBox);const {mountAttendanceHistory}=await import('./attendance-history.js');mountAttendanceHistory({api,el,action},historyBox,id);const photoBox=el('section',undefined,{class:'class-evidence'});box.append(photoBox);const {mountClassEvidence}=await import('./class-evidence.js');if(classSelected!==id||!photoBox.isConnected)return;try{await mountClassEvidence({api,el,field,action,notice},photoBox,id)}catch{photoBox.replaceChildren(el('p','Fotos temporariamente indisponíveis. Você pode continuar lançando a chamada.',{class:'form-error',role:'status'}))}box.scrollIntoView({block:'start'});
}
function setupAttendance(){if($('attendance-area'))return;const area=el('section',undefined,{id:'attendance-area'});$('team-area').before(area);area.append(el('h2','Presença dos alunos'),el('p','1. Escolha núcleo, turma e data. 2. Abra a chamada. 3. Marque os alunos e salve.'));
 const form=el('form',undefined,{id:'class-form'});field(form,'Núcleo da aula','unit','amavale',{options:scopeUnitNames(),htmlId:'class-unit'});field(form,'Turma e horário','group_id','',{options:{},htmlId:'class-group'}).required=true;field(form,'Data da aula','day',todayBR(),{type:'date',max:todayBR()}).required=true;form.append(el('button','Abrir chamada desta turma',{id:'class-open'}));area.append(el('section',undefined,{id:'today-classes',hidden:true}),form,el('section',undefined,{id:'class-detail',hidden:'',tabindex:'-1'}),el('h3','Chamadas já abertas'),el('div',undefined,{id:'class-list'}));
 $('class-unit').addEventListener('change',action(async()=>{$('class-detail').hidden=true;await loadAttendanceGroups()}));form.addEventListener('submit',action(async()=>{const p=await api('/classes',{method:'POST',data:Object.fromEntries(new FormData(form))});await classList();await classDetail(p.lesson.id)}));
 const exportForm=el('form');exportForm.append(el('h3','Exportar presenças CSV'));field(exportForm,'De','from',todayBR().slice(0,7)+'-01',{type:'date'}).required=true;field(exportForm,'Até','to',todayBR(),{type:'date'}).required=true;exportForm.append(el('button','Baixar presenças CSV'));exportForm.addEventListener('submit',action(async()=>{const values=Object.fromEntries(new FormData(exportForm)),query=new URLSearchParams({...values,unit:$('class-unit').value});download(await api('/attendance.csv?'+query,{blob:true}),'presencas.csv')}));area.append(exportForm);
}
document.addEventListener('portal:loaded',action(async()=>{if(['admin','secretary','teacher'].includes(me.role)){const mobile=await attendanceMobileReady;if(attendanceCacheUser!==me.user_id){let storage;try{storage=window.sessionStorage}catch{}attendanceCache=mobile.createAttendanceDraftCache(storage);attendanceDrafts.clear();for(const [id,rows]of attendanceCache.read(me))attendanceDrafts.set(id,rows);attendanceCacheUser=me.user_id}setupAttendance();$('class-open').disabled=me.can_write_attendance!==true;$('class-open').dataset.locked=String(me.can_write_attendance!==true);const {units}=await api('/units');$('attendance-area').hidden=false;const select=$('class-unit'),old=select.value;select.replaceChildren();for(const u of units)select.append(el('option',classUnits[u],{value:u}));if(units.includes(old))select.value=old;if(units.length)await loadAttendanceGroups();else notice('A administração precisa conferir seu cadastro e liberar os núcleos para a chamada.')}else if($('attendance-area'))$('attendance-area').hidden=true}));
document.addEventListener('portal:logout',()=>{$('attendance-area')?.remove();classSelected='';attendanceDrafts.clear();attendanceCache?.clear();attendanceCacheUser=''});

import('./rollcall-panel.js').then(({startRollcallPanel})=>startRollcallPanel({api,el,field,action,notice,active:()=>me,showPanel:(id)=>showPanel(id),openCall:async issue=>{
 setupAttendance();$('class-unit').value=issue.unit;await loadAttendanceGroups();$('class-group').value=issue.group_id;$('class-form').elements.day.value=issue.day;showPanel('attendance-area');
 if(!issue.class_id&&issue.can_write===false){notice('Chamada ainda não aberta. Solicite ao professor responsável, administrador ou secretaria geral.');return;}const lesson=issue.class_id?{id:issue.class_id}:(await api('/classes',{method:'POST',data:{unit:issue.unit,group_id:issue.group_id,day:issue.day}})).lesson;
 await classList();await classDetail(lesson.id);
}})).catch(()=>notice('Não foi possível carregar o acompanhamento de chamadas. Atualize a página.'));
